import{_ as t,o,c as l,a2 as r}from"./chunks/framework.BEUshCVJ.js";const u=JSON.parse('{"title":"延迟偏高","description":"","frontmatter":{},"headers":[],"relativePath":"zh/troubleshooting/latency.md","filePath":"zh/troubleshooting/latency.md","lastUpdated":1792766766000}'),n={name:"zh/troubleshooting/latency.md"};function a(i,e,s,g,h,p){return o(),l("div",null,[...e[0]||(e[0]=[r('<h1 id="延迟偏高" tabindex="-1">延迟偏高 <a class="header-anchor" href="#延迟偏高" aria-label="Permalink to &quot;延迟偏高&quot;">​</a></h1><p>本页用于提示明显慢于约一秒半，或在某些网络下请求失败的情况。</p><h2 id="slow-hints" tabindex="-1">提示要两三秒以上才出现 <a class="header-anchor" href="#slow-hints" aria-label="Permalink to &quot;提示要两三秒以上才出现 {#slow-hints}&quot;">​</a></h2><p><strong>可能原因</strong></p><ol><li>之前选定的端点在当前网络下已经不是最快的。</li><li>要点模型是较大、较慢的模型。</li><li>会前资料太长，每次请求都变大。</li><li>句末静音时长设得较长。</li><li>VPN 或代理绕了远路。</li></ol><p><strong>检查</strong></p><ol><li>鼠标悬停在面板底栏的延迟数字上，查看中位数。</li><li>打开 <strong>设置 › 诊断</strong>：每条提示都会显示识别、检测和要点生成各用了多久。</li></ol><p><strong>解决</strong></p><ol><li>重新运行<a href="/meetcue/zh/guide/latency">延迟探测</a>，应用最快的组合。</li><li>换一个更快的要点模型；探测的组合表会显示差别。</li><li>在 <strong>设置 › 提示</strong> 中保持 <strong>提前触发</strong> 开启。</li><li>把会前资料精简到这场会议需要的部分。</li><li>把 <strong>设置 › 音频 › 高级 › 静音多久算一句结束</strong> 调低一点。</li></ol><p><strong>仍未解决？</strong> <a href="/meetcue/zh/troubleshooting/diagnostics">导出诊断信息</a>并<a href="https://github.com/Amazingkenneth/meetcue/issues/new?template=bug.yml" target="_blank" rel="noreferrer">提交 Issue</a>。</p><h2 id="probe-again" tabindex="-1">面板建议重新探测 <a class="header-anchor" href="#probe-again" aria-label="Permalink to &quot;面板建议重新探测 {#probe-again}&quot;">​</a></h2><p><strong>可能原因</strong></p><ol><li>连续三个问题的延迟超过 2.5 秒。</li></ol><p><strong>检查</strong></p><ol><li>把当前延迟与上次探测结果比较。</li></ol><p><strong>解决</strong></p><ol><li>点击提示中的 <strong>打开延迟探测</strong> 并运行。填写网络标签，便于以后比较不同地点。</li></ol><p><strong>仍未解决？</strong> <a href="/meetcue/zh/troubleshooting/diagnostics">导出诊断信息</a>并<a href="https://github.com/Amazingkenneth/meetcue/issues/new?template=bug.yml" target="_blank" rel="noreferrer">提交 Issue</a>。</p><h2 id="company-network" tabindex="-1">在公司网络下无法连接 <a class="header-anchor" href="#company-network" aria-label="Permalink to &quot;在公司网络下无法连接 {#company-network}&quot;">​</a></h2><p><strong>可能原因</strong></p><ol><li>公司网络用自己的证书检查 HTTPS 流量（<a href="/meetcue/zh/troubleshooting/error-codes#mc-net-001">MC-NET-001</a>）。</li><li>上网需要经过代理，而 MeetCue 不知道这个代理。</li><li>防火墙拦截了语音识别使用的 WebSocket 连接。</li></ol><p><strong>检查</strong></p><ol><li>在同一台电脑的浏览器里打开供应商网站。</li><li>询问 IT 部门是否需要代理，以及代理证书是否已安装到 Windows。</li></ol><p><strong>解决</strong></p><ol><li>MeetCue 信任 Windows 中安装的证书。如果公司证书尚未安装，请 IT 部门把它装入 Windows 证书库。</li><li>在 <strong>设置 › 供应商与费用 › 高级 › HTTPS 代理</strong> 中填写代理，例如 <code>http://proxy.example.com:8080</code>。</li><li>请 IT 部门放行到语音识别供应商主机名（见延迟探测结果）的 WebSocket 连接。</li></ol><p><strong>仍未解决？</strong> <a href="/meetcue/zh/troubleshooting/diagnostics">导出诊断信息</a>并<a href="https://github.com/Amazingkenneth/meetcue/issues/new?template=bug.yml" target="_blank" rel="noreferrer">提交 Issue</a>。</p>',26)])])}const m=t(n,[["render",a]]);export{u as __pageData,m as default};
